class Solution {
    public int findMaximumXOR(int[] nums) {
        int[][] trie = new int[nums.length * 31 + 1][2];   // array-backed trie, 0 = no child
        int size = 1, best = 0;
        for (int x : nums) {
            int n = 0;
            for (int b = 30; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (trie[n][bit] == 0) trie[n][bit] = size++;
                n = trie[n][bit];
            }
        }
        for (int x : nums) {
            int n = 0, cur = 0;
            for (int b = 30; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (trie[n][1 - bit] != 0) { cur |= 1 << b; n = trie[n][1 - bit]; }
                else n = trie[n][bit];
            }
            best = Math.max(best, cur);
        }
        return best;
    }
}

