func findMaximumXOR(nums []int) int {
	type node struct{ next [2]*node }
	root := &node{}
	for _, x := range nums { // binary trie of the numbers, high bit first
		n := root
		for b := 30; b >= 0; b-- {
			bit := x >> b & 1
			if n.next[bit] == nil {
				n.next[bit] = &node{}
			}
			n = n.next[bit]
		}
	}
	best := 0
	for _, x := range nums {
		n, cur := root, 0
		for b := 30; b >= 0; b-- {
			bit := x >> b & 1
			if n.next[1-bit] != nil { // take the opposite bit whenever possible
				cur |= 1 << b
				n = n.next[1-bit]
			} else {
				n = n.next[bit]
			}
		}
		best = max(best, cur)
	}
	return best
}

