			c := w[i] - 'a'
			if n.next[c] == nil {
				n.next[c] = &node{}
			}
			n = n.next[c]
		}
		n.end = true
	}
	shortest := func(word string) string { // the shortest root that prefixes word
		n := root
		for i := 0; i < len(word); i++ {
			if n = n.next[word[i]-'a']; n == nil {
				return word
			}
			if n.end {
				return word[:i+1]
			}
		}
		return word
	}
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = shortest(w)
	}
	return strings.Join(words, " ")
}

